constexpr auto r_vec = noarr::vector<'r'>();
constexpr auto q_vec = noarr::vector<'q'>();
constexpr auto p_vec = noarr::vector<'p'>();
constexpr auto s_vec = noarr::vector<'s'>();

struct tuning {
	// A: r x q x p  (A[r][q][p])
	DEFINE_PROTO_STRUCT(a_layout, p_vec ^ q_vec ^ r_vec);
	// C4: s x p  (C4[s][p])
	DEFINE_PROTO_STRUCT(c4_layout, p_vec ^ s_vec);
	// sum: p  (sum[p])
	DEFINE_PROTO_STRUCT(sum_layout, p_vec);
} tuning;

// Array initialization
void init_array(auto A, auto C4) {
	using namespace noarr;

	// Initialize A[r][q][p] = (r*q + p) % np / np;
	auto np_A = A | get_length<'p'>();
	traverser(A).for_each([=](auto state) {
		auto [r, q, p] = get_indices<'r', 'q', 'p'>(state);
		A[state] = (num_t)((r * q + p) % np_A) / np_A;
	});

	// Initialize C4[s][p] = (s*p) % np / np;
	auto np_C = C4 | get_length<'p'>();
	traverser(C4).for_each([=](auto state) {
		auto [s, p] = get_indices<'s', 'p'>(state);
		C4[state] = (num_t)((s * p) % np_C) / np_C;
	});
}

// Main computational kernel
[[gnu::flatten, gnu::noinline]]
void kernel_doitgen(auto A, auto C4, auto sum) {
	using namespace noarr;

	// View of A where the third dimension is named 's' instead of 'p'
	// so that it matches the 's' dimension of C4 in the inner product.
	auto A_as_s = A ^ rename<'p', 's'>();

#pragma scop
	// for (r)
	//   for (q) {
	//     for (p) {
	//       sum[p] = 0;
	//       for (s)
	//         sum[p] += A[r][q][s] * C4[s][p];
	//     }
	//     for (p)
	//       A[r][q][p] = sum[p];
	//   }
	traverser(A_as_s, C4, sum).template for_dims<'r', 'q'>([=](auto trav_rq) {
		// First nest: compute sum[p] for this (r,q)
		trav_rq.template for_dims<'p'>([=](auto trav_rqp) {
			// sum[p] = 0
			sum[trav_rqp] = SCALAR_VAL(0.0);

			// for (s) sum[p] += A[r][q][s] * C4[s][p];
			trav_rqp.template for_each<'s'>([=](auto state) {
				sum[state] += A_as_s[state] * C4[state];
			});
		});

		// Second nest: A[r][q][p] = sum[p] for this (r,q)
		trav_rq.template for_each<'p'>([=](auto state) {
			A[state] = sum[state];
		});
	});
#pragma endscop
}

} // namespace

int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// problem size
	std::size_t nr = NR;
	std::size_t nq = NQ;
	std::size_t np = NP;

	// set lengths for all used dimensions
	auto set_lengths =
		noarr::set_length<'r'>(nr) ^
		noarr::set_length<'q'>(nq) ^
		noarr::set_length<'p'>(np) ^
		noarr::set_length<'s'>(np);

	// data structures
	auto A   = noarr::bag(noarr::scalar<num_t>() ^ tuning.a_layout   ^ set_lengths);
	auto sum = noarr::bag(noarr::scalar<num_t>() ^ tuning.sum_layout ^ set_lengths);
	auto C4  = noarr::bag(noarr::scalar<num_t>() ^ tuning.c4_layout  ^ set_lengths);

	// initialize arrays
	init_array(A.get_ref(), C4.get_ref());

	// start timer
	auto start = std::chrono::high_resolution_clock::now();

	// run kernel
	kernel_doitgen(A.get_ref(), C4.get_ref(), sum.get_ref());

	// stop timer
	auto end = std::chrono::high_resolution_clock::now();
	auto duration = std::chrono::duration<long double>(end - start);

	// optionally print the result to stderr
	if (argc > 0 && argv[0] != ""s) {
		std::cerr << std::fixed << std::setprecision(2);
		noarr::serialize_data(std::cerr, A.get_ref() ^ noarr::hoist<'r'>());
	}

	// print timing to stdout
	std::cout << std::fixed << std::setprecision(6);
	std::cout << duration.count() << std::endl;

	return 0;
}

