		auto p_len = A | get_length<'p'>();
		A[state] = (num_t)((r * q + p) % p_len) / p_len;
	});

	// Initialize C4[s][p] = (s*p) % np / np
	traverser(C4).for_each([=](auto state) {
		auto [s, p] = get_indices<'s', 'p'>(state);
		auto p_len = C4 | get_length<'p'>();
		C4[state] = (num_t)((s * p) % p_len) / p_len;
	});
