// Main computational kernel
[[gnu::flatten, gnu::noinline]]
void kernel_doitgen(int nr, int nq, int np, auto A, auto C4, auto sum) {
	using namespace noarr;
	(void)nr;
	(void)nq;
	(void)np;

	// View of A where the innermost dimension 'p' is renamed to 's'
