	auto A_s = A ^ noarr::rename<'p', 's'>();

#pragma scop
	traverser(A_s, C4, sum).template for_dims<'r'>([=](auto trav_r) {
		trav_r.template for_dims<'q'>([=](auto trav_rq) {
