			trav_rq.template for_dims<'p'>([=](auto trav_rqp) {
				// (r, q, p) fixed here
				auto state_rqp = trav_rqp.state();

				// sum[p] = 0.0;
				sum[state_rqp] = (num_t)0;

				// for (s = 0; s < NP; s++) sum[p] += A[r][q][s] * C4[s][p];
				trav_rqp.for_each([=](auto state) {
					// state carries (r, q, p, s)
					sum[state_rqp] += A_s[state] * C4[state];
				});
			});

			// for (p = 0; p < NP; p++) A[r][q][p] = sum[p];
			trav_rq.template for_each<'p'>([=](auto state_rqp) {
				A[state_rqp] = sum[state_rqp];
			});
		});
	});
