#include <chrono>
#include <iomanip>
#include <iostream>

#include <noarr/structures_extended.hpp>
#include <noarr/traversers.hpp>
#include <noarr/structures/interop/serialize_data.hpp>

// common PolyBench-style definitions (DATA_TYPE, NR, NQ, NP, ...)
#include "defines.hpp"

// benchmark-specific problem size definitions (NR, NQ, NP)
#include "doitgen.hpp"

using num_t = DATA_TYPE;

namespace {

// dimension descriptors
constexpr auto r_vec = noarr::vector<'r'>(); // rows in A
constexpr auto q_vec = noarr::vector<'q'>(); // columns in A (second dim)
constexpr auto s_vec = noarr::vector<'s'>(); // third dim of A and first dim of C4
constexpr auto p_vec = noarr::vector<'p'>(); // second dim of C4 and dim of sum

// layouts corresponding to C arrays:
//
// C: A[NR][NQ][NP]  -> dims: r, q, s  (NP is innermost, contiguous)
// C: C4[NP][NP]     -> dims: s, p     (p is innermost, contiguous)
// C: sum[NP]        -> dim:  p
constexpr auto A_layout  = s_vec ^ q_vec ^ r_vec;
constexpr auto C4_layout = p_vec ^ s_vec;
constexpr auto sum_layout = p_vec;


// Array initialization, translated to Noarr
// Original C:
//   for (i = 0; i < nr; i++)
//     for (j = 0; j < nq; j++)
//       for (k = 0; k < np; k++)
//         A[i][j][k] = (DATA_TYPE)((i*j + k) % np) / np;
//   for (i = 0; i < np; i++)
//     for (j = 0; j < np; j++)
//       C4[i][j] = (DATA_TYPE)(i*j % np) / np;
void init_array(auto A, auto C4) {
	using namespace noarr;

	// length in the third dimension of A / both dims of C4
	auto np = A | get_length<'s'>();

	// Initialize A[r][q][s]
	traverser(A).for_each([=](auto state) {
		auto [r, q, s] = get_indices<'r', 'q', 's'>(state);
		A[state] = (num_t)((r * q + s) % np) / (num_t)np;
	});

	// Initialize C4[s][p]
	traverser(C4).for_each([=](auto state) {
		auto [s, p] = get_indices<'s', 'p'>(state);
		C4[state] = (num_t)((s * p) % np) / (num_t)np;
	});
}


// Main computational kernel, translated to Noarr traversers.
// Original C:
//
// for (r = 0; r < _PB_NR; r++)
//   for (q = 0; q < _PB_NQ; q++)  {
//     for (p = 0; p < _PB_NP; p++)  {
//       sum[p] = 0.0;
//       for (s = 0; s < _PB_NP; s++)
//         sum[p] += A[r][q][s] * C4[s][p];
//     }
//     for (p = 0; p < _PB_NP; p++)
//       A[r][q][p] = sum[p];
//   }
[[gnu::flatten, gnu::noinline]]
void kernel_doitgen(auto A, auto C4, auto sum) {
	using namespace noarr;

	#pragma scop
	traverser(A, C4, sum).template for_dims<'r'>([=](auto trav_r) {
		trav_r.template for_dims<'q'>([=](auto trav_rq) {

			// First inner nest:
			// for (p) { sum[p] = 0; for (s) sum[p] += A[r][q][s] * C4[s][p]; }
			trav_rq.template for_dims<'p'>([=](auto trav_rqp) {
				// sum[p] = 0.0;
				sum[trav_rqp] = (num_t)0.0;

				// for (s) sum[p] += A[r][q][s] * C4[s][p];
				trav_rqp.template for_dims<'s'>([=](auto trav_rqps) {
					sum[trav_rqp] += A[trav_rqps] * C4[trav_rqps];
				});
			});

			// Second inner loop:
			// for (p) A[r][q][p] = sum[p];
			trav_rq.template for_dims<'p'>([=](auto trav_rqp) {
				auto state_rqp = trav_rqp.state();

				// A has dims (r, q, s); we need to map the loop index p to dim 's'
				auto p_index = get_index<'p'>(state_rqp);
				auto state_rqs = state_rqp.template with<index_in<'s'>>(p_index);

				A[state_rqs] = sum[trav_rqp];
			});
		});
	});
	#pragma endscop
}

} // namespace


int main(int argc, char *argv[]) {
	// problem sizes
	std::size_t nr = NR;
	std::size_t nq = NQ;
	std::size_t np = NP;

	// set lengths for all relevant dimensions
	auto set_lengths =
		noarr::set_length<'r'>(nr) ^
		noarr::set_length<'q'>(nq) ^
		noarr::set_length<'s'>(np) ^
		noarr::set_length<'p'>(np);

	// allocate bags for A, sum, C4
	auto A   = noarr::make_bag(noarr::scalar<num_t>() ^ A_layout  ^ set_lengths);
	auto sum = noarr::make_bag(noarr::scalar<num_t>() ^ sum_layout ^ set_lengths);
	auto C4  = noarr::make_bag(noarr::scalar<num_t>() ^ C4_layout ^ set_lengths);

	// initialize arrays
	init_array(A.get_ref(), C4.get_ref());

	// start timer
	auto start = std::chrono::high_resolution_clock::now();

	// run kernel
	kernel_doitgen(A.get_ref(), C4.get_ref(), sum.get_ref());

	// stop timer
	auto end = std::chrono::high_resolution_clock::now();
	auto duration = std::chrono::duration<long double>(end - start);

	// print result to avoid dead-code elimination
	// (print the full A structure)
	if (argc > 1) {
		std::cerr << std::fixed << std::setprecision(2);
		noarr::serialize_data(std::cerr, A.get_ref() ^ noarr::hoist<'r'>());
	}

	// print timing
	std::cout << std::fixed << std::setprecision(6);
	std::cout << duration.count() << std::endl;

