using num_t = DATA_TYPE;

namespace {

constexpr auto r_vec = noarr::vector<'r'>();
constexpr auto q_vec = noarr::vector<'q'>();
constexpr auto s_vec = noarr::vector<'s'>();
constexpr auto p_vec = noarr::vector<'p'>();

struct tuning {
	// A: r x q x s
	static constexpr auto A_layout   = s_vec ^ q_vec ^ r_vec;
	// C4: s x p (p is the inner dimension)
	static constexpr auto C4_layout  = p_vec ^ s_vec;
	// sum: p
	static constexpr auto sum_layout = p_vec;
} tuning;

// Array initialization
//
// Original C code:
//
// for (i = 0; i < nr; i++)
//   for (j = 0; j < nq; j++)
//     for (k = 0; k < np; k++)
//       A[i][j][k] = (DATA_TYPE)((i*j + k) % np) / np;
//
// for (i = 0; i < np; i++)
//   for (j = 0; j < np; j++)
//     C4[i][j] = (DATA_TYPE)(i*j % np) / np;
//
void init_array(auto A, auto C4) {
	using namespace noarr;

	// A: r x q x s
	traverser(A).for_each([=](auto state) {
		auto [r, q, s] = get_indices<'r', 'q', 's'>(state);
		auto np = A | get_length<'s'>();
		A[state] = (num_t)((r * q + s) % np) / (num_t)np;
	});

	// C4: s x p
	traverser(C4).for_each([=](auto state) {
		auto [s, p] = get_indices<'s', 'p'>(state);
		auto np = C4 | get_length<'p'>();
		C4[state] = (num_t)((s * p) % np) / (num_t)np;
	});
}

// Main computational kernel
//
// Original C kernel:
//
// for (r = 0; r < _PB_NR; r++)
//   for (q = 0; q < _PB_NQ; q++) {
//     for (p = 0; p < _PB_NP; p++) {
//       sum[p] = 0.0;
//       for (s = 0; s < _PB_NP; s++)
//         sum[p] += A[r][q][s] * C4[s][p];
//     }
//     for (p = 0; p < _PB_NP; p++)
//       A[r][q][p] = sum[p];
//   }
//
[[gnu::flatten, gnu::noinline]]
void kernel_doitgen(auto A, auto C4, auto sum) {
	using namespace noarr;

	// A has dimensions r, q, s; we also create a view where s is renamed to p
	// for the write-back phase (A[r][q][p] = sum[p]).
	auto A_p_view = A ^ rename<'s', 'p'>();

#pragma scop
	// Outer loops: r, then q
	traverser(A).template for_dims<'r', 'q'>([=](auto rq_trav) {
		// State with current r and q
		auto rq_state = rq_trav.state(); // contains indices for 'r' and 'q'

		// for (p = 0; p < NP; p++) {
		traverser(sum).for_each([=](auto p_state) {
			// p_state contains index 'p'

			// sum[p] = 0.0;
			sum[p_state] = SCALAR_VAL(0.0);

			// Combine r, q, p into one state for fixing A and C4
			auto rqp_state = rq_state & p_state;

			// for (s = 0; s < NP; s++)
			//   sum[p] += A[r][q][s] * C4[s][p];
			traverser(A, C4)
				.order(noarr::fix(rqp_state)) // fix r, q for A and p for C4
				.template for_dims<'s'>([=](auto s_trav) {
					auto state = s_trav.state(); // has r, q, s, p (r,q,p fixed, s varying)
					sum[p_state] += A[state] * C4[state];
				});
		});

		// for (p = 0; p < NP; p++)
		//   A[r][q][p] = sum[p];
		traverser(sum).for_each([=](auto p_state) {
			auto rqp_state = rq_state & p_state;
			A_p_view[rqp_state] = sum[p_state];
		});
	});
#pragma endscop
}

} // namespace

int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// Problem size
	std::size_t nr = NR;
	std::size_t nq = NQ;
	std::size_t np = NP;

	// Set lengths for all dimensions we will use
	auto set_lengths =
		noarr::set_length<'r'>(nr) ^
		noarr::set_length<'q'>(nq) ^
		noarr::set_length<'s'>(np) ^
		noarr::set_length<'p'>(np);

	// Allocate bags with the desired layouts
	auto A   = noarr::bag(noarr::scalar<num_t>() ^ tuning.A_layout   ^ set_lengths); // r x q x s
	auto C4  = noarr::bag(noarr::scalar<num_t>() ^ tuning.C4_layout  ^ set_lengths); // s x p
	auto sum = noarr::bag(noarr::scalar<num_t>() ^ tuning.sum_layout ^ set_lengths); // p

	// Initialize arrays
	init_array(A.get_ref(), C4.get_ref());

	// Start timer
	auto start = std::chrono::high_resolution_clock::now();

	// Run kernel
	kernel_doitgen(A.get_ref(), C4.get_ref(), sum.get_ref());

	// Stop timer
	auto end = std::chrono::high_resolution_clock::now();
	auto duration = std::chrono::duration<long double>(end - start);

	// Print results to stderr (to prevent dead-code elimination)
	if (argc > 0 && argv[0] != ""s) {
		std::cerr << std::fixed << std::setprecision(2);
		// Hoist 'r' so the outermost dimension in the serialization is NR
		noarr::serialize_data(std::cerr, A.get_ref() ^ noarr::hoist<'r'>());
	}

	// Print elapsed time to stdout
	std::cout << std::fixed << std::setprecision(6);
	std::cout << duration.count() << std::endl;

	return 0;
}
